for f in linter-scripts/check-function-lengths.py linter-scripts/check-placeholder-comments.py linter-scripts/check-prompts-loaded.py linter-scripts/check-readme-canonicals.py linter-scripts/validate-guidelines.py; do sed -i "s/def main().*:/def main() -> int:\n    import sys\n    if hasattr(sys.stdout, \"reconfigure\"):\n        sys.stdout.reconfigure(encoding=\"utf-8\")/g" "$f"; done
